ASM_EXPORT(memcpy);
ASM_EXPORT(memmove);
ASM_EXPORT(memset);
ASM_EXPORT(__memcpy);
ASM_EXPORT(__memmove);
ASM_EXPORT(__memset);
ASM_EXPORT(memcmp);
ASM_EXPORT(strchr);
ASM_EXPORT(strchrnul);
ASM_EXPORT(strcmp);
ASM_EXPORT(strcpy);
ASM_EXPORT(strstr);
ASM_EXPORT(strcat);
ASM_EXPORT(strlen);
